/**
 * Signals in message CHANNEL_STATUS.
 *
 * Per-channel status; sent once per configured channel per second and immediately on status change
 *
 * All signal values are as on the CAN bus.
 */
struct cmc_can_message_channel_status_t {
    /**
     * Output channel number (1-based, matches CHANNEL_OVERVIEW ch01..ch12)
     *
     * Range: 1..16 (1..16 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t channel_number;

    /**
     * 1 = switch is currently driven on
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t is_on;

    /**
     * Channel status code (see VAL_ table)
     *
     * Range: 0..7 (0..7 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t status;

    /**
     * Power consumption in Watts
     *
     * Range: 0..20000 (0..200 W)
     * Scale: 0.01
     * Offset: 0
     */
    uint16_t watts;
};

