/**
 * Signals in message UNIT_INFO.
 *
 * Unit-level telemetry sent every 1 s: supply voltage, MCU die temperature, and total power across all active channels
 *
 * All signal values are as on the CAN bus.
 */
struct cmc_can_message_unit_info_t {
    /**
     * Switch supply voltage in V with 0.01 V resolution; default 12.0 V until sensing HW is added
     *
     * Range: 0..4095 (0..40.95 V)
     * Scale: 0.01
     * Offset: 0
     */
    uint16_t supply_voltage;

    /**
     * STM32G4 die temperature in degC with 0.1°C resolution; show N/A to user when mcu_temp_out_of_range = 1; note ±4.5°C sensor accuracy (datasheet)
     *
     * Range: 0..2047 (-40..164.7 degC)
     * Scale: 0.1
     * Offset: -40
     */
    uint16_t mcu_temp_c;

    /**
     * Sum of watts across all active output channels
     *
     * Range: 0..32767 (0..3276.7 W)
     * Scale: 0.1
     * Offset: 0
     */
    uint16_t total_watts;

    /**
     * 1 = temperature reading is out of valid range; display N/A instead of mcu_temp_c
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t mcu_temp_out_of_range;

    /**
     * MCU VDDA supply voltage measured via VREFINT; 0.01 V per bit
     *
     * Range: 0..511 (0..5.11 V)
     * Scale: 0.01
     * Offset: 0
     */
    uint16_t vfref;
};

